package app;

import app.repositories.CustomerRepository;
import app.repositories.OrderRepository;
import app.repositories.MongoCustomerRepository;
import app.repositories.MongoOrderRepository;
import java.util.function.Function;
import org.springframework.data.mongodb.MongoTransactionManager;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.transaction.support.TransactionTemplate;

/** The repositories over one MongoTemplate, and its transactions: MongoDB has them on replica sets only. */
public class MongoUnitOfWork implements UnitOfWork {
    private final MongoTemplate mongo;
    private final TransactionTemplate transactions;
    private final CustomerRepository customers;
    private final OrderRepository orders;

    public MongoUnitOfWork(MongoTemplate mongo) {
        this.mongo = mongo;
        this.transactions = new TransactionTemplate(new MongoTransactionManager(mongo.getMongoDatabaseFactory()));
        this.customers = new MongoCustomerRepository(mongo);
        this.orders = new MongoOrderRepository(mongo);
    }

    public MongoTemplate mongo() {
        return mongo;
    }

    @Override
    public CustomerRepository customers() {
        return customers;
    }

    @Override
    public OrderRepository orders() {
        return orders;
    }

    @Override
    public <T> T transaction(Function<UnitOfWork, T> work) {
        // Joins the transaction already open
        return transactions.execute((status) -> work.apply(this));
    }
}

