        return new Page<>(items, mongo.count(new Query(), Order.class), offset, limit);
    }

    @Override
    public List<Order> listByCustomer(Long customer) {
        return mongo.find(Query.query(Criteria.where("customer").is(customer)).with(Sort.by("id")), Order.class).stream().map(this::loaded).toList();
    }

    @Override
    public Order insert(Order entity) {
        try {
            mongo.insert(entity);
        } catch (DataAccessException error) {
            throw Documents.refusal("Order", error);
        }
        return loaded(entity);
    }

    @Override
    public Order update(Order entity) {
        Document now = Documents.of(mongo, entity);
        Document changes = Documents.changes(LOADED.get(entity), now, FIELDS);
        try {
            if (!changes.isEmpty()) mongo.execute(Order.class, (collection) -> collection.updateOne(Filters.eq("_id", now.get("_id")), changes));
        } catch (DataAccessException error) {
            throw Documents.refusal("Order", error);
        }
        return loaded(entity);
    }

    @Override
    public void delete(Order entity) {
        try {
            mongo.remove(Query.query(Criteria.where("id").is(entity.getId())), Order.class);
        } catch (DataAccessException error) {
            throw Documents.refusal("Order", error);
        }
    }

    @Override
    public Optional<Order> addLine(Long id, Order.Line line) {
        Document change = new Document("$push", new Document("lines", Documents.of(mongo, line)));
        Document filter = new Document("_id", id);
        FindOneAndUpdateOptions after = new FindOneAndUpdateOptions().returnDocument(ReturnDocument.AFTER);
        Document changed;
        try {
            changed = mongo.execute(Order.class, (collection) -> collection.findOneAndUpdate(filter, change, after));
        } catch (DataAccessException error) {
            throw Documents.refusal("Order", error);
        }
        return Optional.ofNullable(changed).map((document) -> loaded(mongo.getConverter().read(Order.class, document)));
    }

    @Override
    public Optional<Order> removeLine(Long id, int position, int size) {
        Document head = new Document("$slice", List.of("$lines", position));
        Document tail = new Document("$slice", List.of("$lines", position + 1, Math.max(size, 1)));
        List<Document> change = List.of(new Document("$set", new Document("lines", new Document("$concatArrays", List.of(head, tail)))));
        Document filter = new Document("_id", id).append("lines", new Document("$size", size));
        FindOneAndUpdateOptions after = new FindOneAndUpdateOptions().returnDocument(ReturnDocument.AFTER);
        Document changed;
        try {
            changed = mongo.execute(Order.class, (collection) -> collection.findOneAndUpdate(filter, change, after));
        } catch (DataAccessException error) {
            throw Documents.refusal("Order", error);
        }
        return Optional.ofNullable(changed).map((document) -> loaded(mongo.getConverter().read(Order.class, document)));
    }

    /** The same entity, with what it is stored as kept to tell its changes. */
    private Order loaded(Order entity) {
        LOADED.put(entity, Documents.of(mongo, entity));
        return entity;
    }
