            }
        }
        {
            Object value = values.get("customer");
            if (value == null) {
                if (creating || values.containsKey("customer")) errors.add(new FieldError("customer", "is required"));
            }
        }
        {
            Object value = values.get("status");
            if (value == null) {
                if (creating || values.containsKey("status")) errors.add(new FieldError("status", "is required"));
            } else {
                if (!List.of("new", "paid", "sent").contains(String.valueOf(value))) errors.add(new FieldError("status", "must be one of: new, paid, sent"));
            }
        }
        {
            Object value = values.get("total");
            if (value == null) {
                if (creating || values.containsKey("total")) errors.add(new FieldError("total", "is required"));
