    @SuppressWarnings("unchecked")
    private static void apply(Order entity, Map<String, Object> values) {
        if (values.containsKey("id")) entity.setId((Long) values.get("id"));
        if (values.containsKey("customer")) entity.setCustomer((Long) values.get("customer"));
        if (values.containsKey("status")) entity.setStatus((String) values.get("status"));
        if (values.containsKey("total")) entity.setTotal((Double) values.get("total"));
        if (values.containsKey("placedAt")) entity.setPlacedAt((Instant) values.get("placedAt"));
        if (values.containsKey("lines")) entity.setLines((List<Order.Line>) values.get("lines"));
    }

    /** The Order with this key; NotFoundException when there is none. */
