    /** What a Line does not follow of its rules, each with the path of its field. */
    private static void checkLine(Order.Line value, String path, List<FieldError> errors) {
        if (value.getProduct() == null) errors.add(new FieldError(path + ".product", "is required"));
        if (value.getQuantity() == null) errors.add(new FieldError(path + ".quantity", "is required"));
